settings.custom_liquid:
{% comment %}
  Home banner - מיסטרי בוקס
  Floating card version: the banner sits inside the page with rounded corners,
  so it no longer slams into the beige header as a hard black block.
  The whole banner is a link. ✏️ banner_link = where a click goes.
{% endcomment %}

{%- assign banner_link = '/pages/יוצר-מיסטרי' -%}

<style>
  .shopify-section-custom-liquid:has(#ny-edge-banner-01) { padding: 0 !important; margin: 0 !important; }

  #ny-edge-banner-01 {
    display: block;
    max-width: 1680px;
    margin: 18px auto 0;
    padding: 0 18px;
  }
  #ny-edge-banner-01 a {
    display: block; position: relative; line-height: 0;
    border-radius: 26px; overflow: hidden;
    box-shadow: 0 1px 0 rgba(0,0,0,.04), 0 18px 40px -18px rgba(0,0,0,.45);
    transition: transform .3s ease, box-shadow .3s ease;
  }
  #ny-edge-banner-01 a:hover { transform: translateY(-2px); box-shadow: 0 1px 0 rgba(0,0,0,.04), 0 26px 50px -18px rgba(0,0,0,.5); }
  #ny-edge-banner-01 a:focus-visible { outline: 3px solid #121212; outline-offset: 4px; }
  #ny-edge-banner-01 picture, #ny-edge-banner-01 img { display: block; width: 100%; height: auto; }

  @media screen and (max-width: 749px) {
    #ny-edge-banner-01 { margin-top: 10px; padding: 0 10px; }
    #ny-edge-banner-01 a { border-radius: 18px; }
  }
  @media (prefers-reduced-motion: reduce) { #ny-edge-banner-01 a { transition: none; } }
</style>

<div id="ny-edge-banner-01">
  <a href="{{ banner_link }}" aria-label="מיסטרי בוקס לצוות: 79₪ לחולצת 26/27 ו־89₪ לרטרו, בהזמנת 5 חולצות ומעלה">
    <picture>
      <source media="(max-width: 749px)"
              srcset="https://cdn.shopify.com/s/files/1/0707/4938/9043/files/hashofet-banner-mobile_fcf98bf1-7e22-4974-a9f9-eeef3076da14.webp?v=1789130135"
              width="1856" height="2304">
      <img src="https://cdn.shopify.com/s/files/1/0707/4938/9043/files/hashofet-banner-desktop_6093229f-e531-4d5e-9809-4503d36639b3.webp?v=1789130135"
           width="3232" height="1312"
           alt="מיסטרי בוקס: עונת 26/27 ב־79₪ ורטרו ב־89₪ לחולצה, בהזמנת 5 חולצות ומעלה"
           loading="eager" fetchpriority="high" decoding="async">
    </picture>
  </a>
</div>

{% comment %}
  לקוחות מספרים 💬 - v7 (light theme)
  The button now scrolls down to the "קבוצות פופולריות" section on the same page.
  Paste into: Add section → Custom Liquid
  ✏️ EDIT the trust badge numbers to your real stats.
{% endcomment %}

<style>
  /* pinch this section against the banner above */
  .shopify-section:has(> .hsr),
  .shopify-section:has(.hsr) {
    margin-top: 0 !important;
    padding-top: 0 !important;
  }
  .hsr { margin-top: 0; }

  .hsr {
    direction: rtl;
    padding: 56px 0 64px;
    overflow: hidden;
    background:
      radial-gradient(ellipse 65% 45% at 50% 35%, rgba(37,211,102,.05), rgba(37,211,102,0) 75%),
      #FAF9F6;
  }
  .hsr__head { text-align: center; padding: 0 20px; }
  .hsr__badge {
    display: inline-flex; align-items: center; gap: 7px;
    background: rgba(37,211,102,.10);
    border: 1px solid rgba(37,211,102,.4);
    color: #128C4B; font-size: 13px; font-weight: 700;
    padding: 7px 16px; border-radius: 100px; margin-bottom: 26px;
  }
  .hsr__title {
    font-size: 32px; font-weight: 800; color: #121212;
    margin: 0 0 10px; letter-spacing: -0.5px;
  }
  .hsr__sub { font-size: 15px; color: #6b7280; margin: 0 0 28px; }

  /* ---- trust badges ---- */
  .hsr__trust {
    display: flex; flex-wrap: wrap; justify-content: center; gap: 12px;
    margin: 0 auto 22px; padding: 0 20px; max-width: 760px;
  }
  .hsr__trust-item {
    display: flex; align-items: center; gap: 9px;
    background: #ffffff;
    border: 1px solid #e7e7e7;
    border-radius: 14px; padding: 10px 18px;
    box-shadow: 0 2px 10px rgba(0,0,0,.05);
  }
  .hsr__trust-icon { font-size: 18px; line-height: 1; }
  .hsr__trust-num { color: #121212; font-size: 15px; font-weight: 800; line-height: 1.1; }
  .hsr__trust-label { color: #6b7280; font-size: 11.5px; line-height: 1.1; }

  .hsr__badge-row { text-align: center; padding: 0 20px; }

  /* ---- marquee ---- */
  .hsr__viewport { position: relative; overflow: hidden; direction: ltr; }
  .hsr__marquee {
    display: flex; flex-wrap: nowrap; width: max-content;
    padding: 6px 0 10px;
    animation: hsr-scroll 55s linear infinite !important;
    animation-play-state: running;
    will-change: transform;
  }
  @media (hover: hover) and (pointer: fine) {
    .hsr__viewport:hover .hsr__marquee { animation-play-state: paused; }
  }
  .hsr__viewport::before, .hsr__viewport::after {
    content: ""; position: absolute; top: 0; bottom: 0; width: 90px; z-index: 2; pointer-events: none;
  }
  .hsr__viewport::before { right: 0; background: linear-gradient(to left, #FAF9F6, transparent); }
  .hsr__viewport::after  { left: 0;  background: linear-gradient(to right, #FAF9F6, transparent); }
  @keyframes hsr-scroll {
    from { transform: translate3d(-50%, 0, 0); }
    to   { transform: translate3d(0, 0, 0); }
  }

  /* ---- cards ---- */
  .hsr__card {
    direction: rtl;
    position: relative; flex: 0 0 auto; width: 230px;
    margin: 0 9px;
    border-radius: 20px; overflow: hidden;
    border: 1px solid #ececec;
    box-shadow: 0 6px 20px rgba(0,0,0,.10);
    transition: transform .3s ease, border-color .3s ease, box-shadow .3s ease;
    background: #f6f6f6;
  }
  .hsr__card:hover {
    transform: scale(1.03);
    border-color: rgba(37,211,102,.55);
    box-shadow: 0 12px 28px rgba(0,0,0,.14);
  }
  .hsr__img { width: 100%; height: auto; aspect-ratio: 9/16; object-fit: cover; display: block; }
  .hsr__chip {
    position: absolute; top: 10px; right: 10px; z-index: 1;
    display: flex; align-items: center; gap: 5px;
    background: rgba(255,255,255,.92); backdrop-filter: blur(4px);
    border: 1px solid rgba(37,211,102,.5);
    color: #128C4B; font-size: 10.5px; font-weight: 700;
    padding: 4px 9px; border-radius: 100px;
  }
  .hsr__chip svg { width: 11px; height: 11px; }

  .hsr__cta { text-align: center; margin-top: 34px; padding: 0 20px; }
  .hsr__cta a {
    display: inline-flex; align-items: center; gap: 8px;
    background: #25D366; color: #ffffff; text-decoration: none;
    font-size: 15px; font-weight: 800;
    padding: 13px 28px; border-radius: 100px;
    transition: transform .2s ease, box-shadow .2s ease;
    box-shadow: 0 6px 20px rgba(37,211,102,.3);
  }
  .hsr__cta a:hover { transform: translateY(-2px); box-shadow: 0 10px 26px rgba(37,211,102,.4); }
  .hsr__cta a:focus-visible { outline: 3px solid #121212; outline-offset: 3px; }
  .hsr__cta svg { width: 16px; height: 16px; }

  @media (max-width: 749px) {
    .hsr { padding: 44px 0 52px; }
    .hsr__title { font-size: 25px; }
    .hsr__card { width: 185px; margin: 0 6px; }
    .hsr__trust { gap: 8px; }
    .hsr__trust-item { padding: 8px 13px; border-radius: 12px; }
    .hsr__trust-num { font-size: 13.5px; }
    .hsr__marquee { animation-duration: 40s !important; }
    .hsr__viewport::before, .hsr__viewport::after { width: 36px; }
  }
  @media (prefers-reduced-motion: reduce) {
    .hsr__marquee { animation-duration: 90s !important; }
  }
</style>

{% assign review_images = "6_c1fecba6-c631-440e-ad1d-3fb6ac62a2eb.png,7_a2d206bf-bad0-4736-a19d-1e3f84bd693c.png,5_6acb0f1d-a744-4b20-a0a6-e962eb748741.png,8_c2d91632-4c4e-413e-9230-0e61a9dcd30d.png,1_79886716-beae-4cde-8fff-51506f77a633.png,2_568ef9de-2f55-49a3-85ff-e4e964fa92bb.png,4_08c2050c-d33c-42ec-926c-361f7276313c.png,3_0e189494-fda6-4b10-9ce3-ccb195a846e9.png,4_6a72219f-c7f9-4918-90ce-22f56b49790b.png,5_14589324-d403-4a07-8a9c-084812f35dfa.png,1_a8be09c9-b5ea-4b5c-9d12-dde0ab8516ed.png,2_5736408d-a8a9-4eb1-a44e-f1ab24136454.png,6_8afa7e44-a22c-451c-9ed2-7fd8cc7db2b2.png,7_7a82ba32-78fb-463d-bfbf-53f0df243d47.png,8_30a6065e-b271-4748-a44c-f53e0eb7067b.png" | split: "," %}

