  <!-- ✏️ EDIT these numbers to your real stats -->
  <div class="hsr__trust">
    <div class="hsr__trust-item">
      <span class="hsr__trust-icon">📦</span>
      <div><div class="hsr__trust-num">+2,000</div><div class="hsr__trust-label">הזמנות נשלחו</div></div>
    </div>
    <div class="hsr__trust-item">
      <span class="hsr__trust-icon">⭐</span>
