      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 5v14M6 13l6 6 6-6"/></svg>
    </a>
  </div>
</div>

<script>
(function () {
  document.querySelectorAll('.hsr [data-scroll-to]').forEach(function (btn) {
    if (btn.dataset.ready) return;
    btn.dataset.ready = '1';
    btn.addEventListener('click', function (e) {
      var want = btn.dataset.scrollTo;
      var heads = document.querySelectorAll('h1, h2, h3');
      var target = null;
      for (var i = 0; i < heads.length; i++) {
        if (heads[i].textContent.indexOf(want) > -1) { target = heads[i]; break; }
      }
      if (!target) return;                     // section not on this page: normal link to all products
      e.preventDefault();
      var header = document.querySelector('.section-header, header');
      var offset = header ? header.getBoundingClientRect().height + 16 : 90;
      var y = target.getBoundingClientRect().top + window.pageYOffset - offset;
      var smooth = !window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      window.scrollTo({ top: y, behavior: smooth ? 'smooth' : 'auto' });
    });
  });
})();
</script>

{% comment %}
  חולצות חמות - custom section
  Paste into: Home page → Add section → Custom Liquid (replace the old "חולצות חמות" section)
  ✏️ Change the handles below to swap products (the part after /products/ in the URL).
{% endcomment %}

{%- assign hot_handles = 'ברזיל-1998-בית,ברצלונה-2025-מהדורה-מיוחדת,ריאל-מדריד-14-15-שלישית,ארגנטינה-1994-חוץ' | split: ',' -%}

<style>
  .hot {
    --ink: #121212; --muted: #6b6860; --tile: #efece3; --line: #e2ded3; --red: #d8322b;
    direction: rtl; color: var(--ink); font-family: inherit;
    padding: 56px 0 60px;
  }
  .hot__wrap { max-width: 1240px; margin: 0 auto; padding: 0 20px; }
  .hot__head { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; margin-bottom: 22px; }
  .hot__title { margin: 0; font-size: clamp(30px, 4vw, 46px); font-weight: 900; letter-spacing: -0.02em; line-height: 1.05; }
  .hot__all { font-size: 15px; font-weight: 800; color: var(--ink); text-underline-offset: 4px; white-space: nowrap; }

  .hot__grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }
  .hot__card {
    position: relative; display: flex; flex-direction: column;
    text-decoration: none; color: var(--ink);
    background: #fff; border: 1px solid var(--line); border-radius: 22px; overflow: hidden;
    transition: transform .25s ease, box-shadow .25s ease;
  }
  .hot__card:hover { transform: translateY(-4px); box-shadow: 0 18px 36px rgba(0,0,0,.10); }
  .hot__card:focus-visible { outline: 3px solid var(--ink); outline-offset: 3px; }

  .hot__media { position: relative; aspect-ratio: 1 / 1; background: var(--tile); overflow: hidden; }
  .hot__year {
    position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
    font-size: clamp(90px, 9vw, 140px); font-weight: 900; letter-spacing: -0.04em; line-height: 1;
    color: transparent; -webkit-text-stroke: 2px rgba(18,18,18,.10);
    direction: ltr; pointer-events: none; user-select: none;
  }
  .hot__img {
    position: absolute; inset: 6%; width: 88%; height: 88%; object-fit: contain;
    filter: drop-shadow(0 14px 16px rgba(0,0,0,.16));
    transition: opacity .35s ease, transform .35s ease;
  }
  .hot__img--2 { opacity: 0; }
  .hot__card:hover .hot__img--1.has-2 { opacity: 0; }
  .hot__card:hover .hot__img--2 { opacity: 1; }
  .hot__card:hover .hot__img { transform: scale(1.04); }

  .hot__off {
    position: absolute; top: 12px; right: 12px; z-index: 2;
    background: var(--red); color: #fff; font-size: 13px; font-weight: 900;
    padding: 5px 11px; border-radius: 100px; direction: rtl;
  }
  .hot__sold { background: var(--ink); }

  .hot__info { padding: 14px 16px 16px; display: flex; flex-direction: column; gap: 2px; flex: 1; }
  .hot__team { font-size: 19px; font-weight: 900; line-height: 1.2; }
  .hot__meta { font-size: 14px; color: var(--muted); font-weight: 600; }
  .hot__buy { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: 12px; }
  .hot__price { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
  .hot__price b { font-size: 24px; font-weight: 900; font-variant-numeric: tabular-nums; }
  .hot__price small { font-size: 13px; font-weight: 700; color: var(--muted); }
  .hot__price s { font-size: 14px; color: var(--muted); }
  .hot__go {
    flex-shrink: 0; width: 40px; height: 40px; border-radius: 50%;
    background: var(--ink); color: #fff; display: flex; align-items: center; justify-content: center;
    transition: transform .25s ease;
  }
  .hot__go svg { width: 18px; height: 18px; }
  .hot__card:hover .hot__go { transform: translateX(-3px); }

  @media (max-width: 900px) {
    .hot { padding: 40px 0 44px; }
    .hot__grid { grid-template-columns: repeat(2, 1fr); gap: 10px; }
    .hot__team { font-size: 16px; }
    .hot__meta { font-size: 13px; }
    .hot__price b { font-size: 20px; }
    .hot__go { width: 34px; height: 34px; }
    .hot__info { padding: 12px; }
  }
  @media (prefers-reduced-motion: reduce) { .hot__card, .hot__img, .hot__go { transition: none; } }
</style>

<section class="hot" aria-label="חולצות חמות">
  <div class="hot__wrap">
    <div class="hot__head">
      <h2 class="hot__title">חולצות חמות 🔥</h2>
      <a class="hot__all" href="/collections/all">לכל החולצות</a>
    </div>

    <div class="hot__grid">
      {%- for h in hot_handles -%}
        {%- assign p = all_products[h] -%}
        {%- if p == blank or p.id == blank -%}{%- continue -%}{%- endif -%}

        {%- assign parts = p.title | split: '|' -%}
        {%- assign team = parts.first | strip -%}
        {%- assign meta = '' -%}
        {%- assign year = '' -%}
        {%- for part in parts offset: 1 -%}
          {%- assign t = part | strip -%}
          {%- assign as_num = t | plus: 0 -%}
          {%- if as_num > 1900 and as_num < 2100 -%}{%- assign year = t -%}{%- endif -%}
          {%- if year == '' and t contains '/' and t.size <= 7 -%}{%- assign year = t -%}{%- endif -%}
          {%- if meta != '' -%}{%- assign meta = meta | append: ' | ' -%}{%- endif -%}
          {%- assign meta = meta | append: t -%}
        {%- endfor -%}

        {%- assign off = 0 -%}
        {%- if p.compare_at_price > p.price -%}
          {%- assign off = p.compare_at_price | minus: p.price | times: 100 | divided_by: p.compare_at_price -%}
        {%- endif -%}

        <a class="hot__card" href="{{ p.url }}">
          <div class="hot__media">
            {%- if year != '' -%}<span class="hot__year" aria-hidden="true">{{ year }}</span>{%- endif -%}
            {%- if p.available == false -%}
              <span class="hot__off hot__sold">אזל</span>
            {%- elsif off > 0 -%}
              <span class="hot__off">{{ off }}%-</span>
            {%- endif -%}
            {%- if p.featured_image -%}
              <img class="hot__img hot__img--1{% if p.images.size > 1 %} has-2{% endif %}" src="{{ p.featured_image | image_url: width: 700 }}" alt="{{ p.title | escape }}" loading="lazy" decoding="async" width="700" height="700">
            {%- endif -%}
            {%- if p.images.size > 1 -%}
              <img class="hot__img hot__img--2" src="{{ p.images[1] | image_url: width: 700 }}" alt="" aria-hidden="true" loading="lazy" decoding="async" width="700" height="700">
            {%- endif -%}
          </div>
          <div class="hot__info">
            <span class="hot__team">{{ team }}</span>
            {%- if meta != '' -%}<span class="hot__meta">{{ meta }}</span>{%- endif -%}
            <div class="hot__buy">
              <span class="hot__price">
                {%- if p.price_varies -%}<small>החל מ־</small>{%- endif -%}
                <b>{{ p.price | money_without_trailing_zeros | remove: ' ' }}</b>
                {%- if p.compare_at_price > p.price -%}<s>{{ p.compare_at_price | money_without_trailing_zeros | remove: ' ' }}</s>{%- endif -%}
              </span>
              <span class="hot__go" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M15 18l-6-6 6-6"/></svg></span>
            </div>
          </div>
        </a>
      {%- endfor -%}
    </div>
  </div>
</section>

{% comment %}
  HOME PAGE VERSION - מיסטרי בוקס (hero + photo wall + collapsible team order builder)
  Paste into: Home page → Add section → Custom Liquid
  ✏️ group_min / group_off = when the group price starts and how much it takes off each shirt (in ₪).
{% endcomment %}

