{%- assign ugc_list = ugc | strip_newlines | split: '|' -%}

{%- if mp and mp.variants.size > 0 -%}
<style>
  .tob {
    --ink: #121212; --muted: #6b6860; --paper: #f6f5f1; --sand: #efece3; --line: #e2ded3;
    --green: #1a9c52; --navy: #14234f; --maroon: #7d1d2c; --kraft: #c29a6b;
    direction: rtl; background: transparent; color: var(--ink);  /* inherits the theme's own background, no seam */
    padding: 64px 0 60px; font-family: inherit; overflow: hidden;
    /* full-bleed even if the theme wraps sections in a container */
    width: var(--tob-vw, 100vw); margin-left: calc(50% - var(--tob-vw, 100vw) / 2); margin-right: calc(50% - var(--tob-vw, 100vw) / 2);
  }
  .tob__wrap { max-width: 1120px; margin: 0 auto; padding: 0 20px; }

  /* header */
  .tob__hero { display: grid; grid-template-columns: 1.2fr 1fr; gap: 24px; align-items: center; max-width: 1120px; margin: 0 auto 10px; padding: 0 20px; }
  .tob__title { margin: 0; font-size: clamp(44px, 6.4vw, 84px); font-weight: 900; line-height: .95; letter-spacing: -0.03em; }
  .tob__for { display: block; font-size: clamp(22px, 2.6vw, 32px); font-weight: 800; color: var(--muted); margin-top: 8px; }
  .tob__prices { display: flex; gap: 12px; margin-top: 20px; flex-wrap: wrap; }
  .tob__price { display: flex; align-items: baseline; gap: 8px; background: #fff; border: 1px solid var(--line); border-right: 6px solid var(--kit); border-radius: 14px; padding: 10px 16px; }
  .tob__price b { font-size: 30px; font-weight: 900; font-variant-numeric: tabular-nums; }
  .tob__price span { font-size: 14px; font-weight: 700; color: var(--kit); }
  .tob__cond { margin: 12px 0 0; font-size: 15px; color: var(--muted); }
  .tob__boximg { position: relative; justify-self: center; width: min(420px, 100%); }
  .tob__boximg img { width: 100%; height: auto; display: block; filter: drop-shadow(0 26px 30px rgba(0,0,0,.18)); animation: tobFloat 5s ease-in-out infinite; }
  .tob__ill { display: block; text-align: center; font-size: 11.5px; color: var(--muted); margin-top: 4px; }
  @keyframes tobFloat { 0%,100% { transform: translateY(0) rotate(-1deg); } 50% { transform: translateY(-10px) rotate(1deg); } }

  /* photo wall: always the full screen width, no empty edge */
  .tob__wall {
    position: relative; overflow: hidden; direction: ltr;
    margin: 26px 0 34px; padding: 18px 0 26px;
  }
  .tob__track { display: flex; width: max-content; animation: tobScroll 70s linear infinite; }
  @media (hover: hover) and (pointer: fine) { .tob__wall:hover .tob__track { animation-play-state: paused; } }
  @keyframes tobScroll { from { transform: translate3d(-50%,0,0); } to { transform: translate3d(0,0,0); } }
  .tob__shot { position: relative; flex: 0 0 auto; margin: 0 12px; background: #fff; padding: 8px; border-radius: 18px; box-shadow: 0 14px 30px rgba(0,0,0,.14); transform: rotate(var(--r, 0deg)); }
  .tob__shot:nth-child(odd) { --r: -1.6deg; } .tob__shot:nth-child(even) { --r: 1.4deg; }
  .tob__shot img { height: 320px; width: auto; display: block; border-radius: 12px; background: #ddd; }
  .tob__chip { position: absolute; top: 18px; right: 18px; direction: rtl; background: rgba(18,18,18,.82); color: #fff; font-size: 12.5px; font-weight: 800; padding: 5px 11px; border-radius: 100px; }

  /* collapsible builder */
  .tob__builder { max-width: 1120px; margin: 0 auto; padding: 0 20px; }
  .tob__toggle {
    width: 100%; display: flex; align-items: center; gap: 16px; text-align: right;
    background: var(--ink); color: #fff; border: 0; border-radius: 22px; padding: 18px 22px; cursor: pointer; font: inherit;
  }
  .tob__toggle svg.box { width: 46px; height: 44px; flex-shrink: 0; }
  .tob__tt { flex: 1; }
  .tob__tt b { display: block; font-size: 20px; font-weight: 900; }
  .tob__tt span { font-size: 14px; opacity: .75; }
  .tob__open {
    display: inline-flex; align-items: center; gap: 8px; background: #fff; color: var(--ink);
    font-weight: 900; font-size: 16px; padding: 12px 20px; border-radius: 14px; white-space: nowrap;
  }
  .tob__open svg { width: 16px; height: 16px; transition: transform .3s ease; }
  .tob__builder.is-open .tob__open svg { transform: rotate(180deg); }
  .tob__toggle:focus-visible { outline: 3px solid var(--ink); outline-offset: 3px; }
  .tob__panel { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .45s ease; }
  .tob__builder.is-open .tob__panel { grid-template-rows: 1fr; }
  .tob__panel > div { overflow: hidden; }
  .tob__builder.is-done .tob__panel > div { overflow: visible; }
  .tob__grid { display: grid; grid-template-columns: 1.55fr 1fr; gap: 22px; align-items: start; padding-top: 16px; }

  .tob__box { background: #fff; border: 1px solid var(--line); border-radius: 22px; padding: 22px; }
  .tob__h { font-size: 17px; font-weight: 800; margin: 0 0 14px; display: flex; justify-content: space-between; align-items: center; }
  .tob__count { display: inline-flex; align-items: center; border: 1px solid var(--line); border-radius: 100px; overflow: hidden; }
  .tob__count button { width: 38px; height: 36px; border: 0; background: var(--sand); font-size: 20px; font-weight: 800; cursor: pointer; color: var(--ink); }
  .tob__count output { min-width: 44px; text-align: center; font-weight: 900; font-size: 17px; }
  .tob__rows { display: grid; gap: 8px; }
  .tob__row { display: grid; grid-template-columns: 38px 1fr 1.4fr 32px; gap: 8px; align-items: center; padding: 8px; border-radius: 14px; background: var(--paper); }
  .tob__row.is-bad { outline: 2px solid #d9534f; }
  .tob__n { position: relative; width: 36px; height: 34px; display: flex; align-items: center; justify-content: center; }
  .tob__n svg { position: absolute; inset: 0; width: 100%; height: 100%; }
  .tob__n b { position: relative; z-index: 1; font-size: 12px; font-weight: 900; color: #fff; margin-top: 7px; }
  .tob select, .tob input[type=text] { width: 100%; height: 40px; border: 1px solid var(--line); border-radius: 10px; background: #fff; font: inherit; font-size: 14px; padding: 0 10px; color: var(--ink); }
  .tob select:focus-visible, .tob input:focus-visible, .tob button:focus-visible, .tob a:focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; }
  .tob__del { width: 32px; height: 32px; border: 0; background: none; border-radius: 8px; cursor: pointer; color: var(--muted); font-size: 20px; }
  .tob__del:hover { background: var(--sand); color: var(--ink); }
  .tob__add { margin-top: 10px; width: 100%; height: 44px; border: 1.5px dashed #c9c4b6; background: none; border-radius: 12px; font: inherit; font-weight: 800; font-size: 15px; cursor: pointer; color: var(--ink); }
  .tob__add:hover { background: var(--sand); }
  .tob__team { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 16px; padding-top: 16px; border-top: 1px dashed var(--line); }
  .tob__team label { font-size: 13px; font-weight: 700; color: var(--muted); display: grid; gap: 6px; }

  .tob__sum { position: sticky; top: 90px; }
  .tob__bar { height: 10px; border-radius: 100px; background: var(--sand); overflow: hidden; margin: 4px 0 8px; }
  .tob__bar i { display: block; height: 100%; width: 0; background: var(--ink); border-radius: 100px; transition: width .35s ease, background .35s ease; }
  .tob.is-group .tob__bar i { background: var(--green); }
  .tob__msg { font-size: 14px; font-weight: 700; margin: 0 0 16px; min-height: 20px; }
  .tob.is-group .tob__msg { color: var(--green); }
  .tob__line { display: flex; justify-content: space-between; font-size: 15px; padding: 6px 0; }
  .tob__line s { color: var(--muted); }
  .tob__total { display: flex; justify-content: space-between; align-items: baseline; padding-top: 10px; margin-top: 6px; border-top: 1px solid var(--line); }
  .tob__total b { font-size: 34px; font-weight: 900; font-variant-numeric: tabular-nums; }
  .tob__save { display: inline-block; margin-top: 10px; background: #e6f5ec; color: var(--green); font-weight: 800; font-size: 15px; padding: 6px 14px; border-radius: 100px; }
  .tob__save:empty { display: none; }
  .tob__go { margin-top: 18px; width: 100%; height: 58px; border: 0; border-radius: 16px; cursor: pointer; background: var(--ink); color: #fff; font: inherit; font-size: 18px; font-weight: 900; transition: transform .15s ease, opacity .2s ease; }
  .tob__go:hover { transform: translateY(-2px); }
  .tob__go[disabled] { opacity: .55; cursor: default; transform: none; }
  .tob__err { color: #c0392b; font-size: 14px; font-weight: 700; margin: 10px 0 0; }
  .tob__err:empty { display: none; }
  .tob__fine { font-size: 12.5px; color: var(--muted); margin: 10px 0 0; text-align: center; }
  .tob__kids { display: block; text-align: center; margin-top: 16px; font-weight: 800; color: var(--ink); text-underline-offset: 3px; }
  .tob__more { display: block; text-align: center; margin-top: 22px; font-weight: 800; color: var(--ink); text-underline-offset: 3px; }

  @media (max-width: 900px) {
    .tob { padding: 48px 0 44px; }
    .tob__hero { grid-template-columns: 1fr; text-align: center; }
    .tob__prices { justify-content: center; }
    .tob__boximg { width: min(280px, 80%); grid-row: 1; }
    .tob__shot img { height: 210px; }
    .tob__track { animation-duration: 50s; }
    .tob__toggle { flex-wrap: wrap; }
    .tob__open { width: 100%; justify-content: center; }
    .tob__grid { grid-template-columns: 1fr; }
    .tob__sum { position: static; }
    .tob__team { grid-template-columns: 1fr; }

  }
  @media (prefers-reduced-motion: reduce) {
    .tob__bar i, .tob__go, .tob__panel, .tob__open svg { transition: none; }
    .tob__boximg img { animation: none; }
    .tob__track { animation-duration: 140s; }
  }
</style>

<section class="tob" id="tob-{{ section.id }}" aria-label="מיסטרי בוקס לצוות">
  <div class="tob__hero">
    <div>
      <h2 class="tob__title">מיסטרי בוקס<span class="tob__for">לכל הצוות</span></h2>
      <div class="tob__prices">
        <span class="tob__price" style="--kit: var(--navy)"><b>79₪</b><span>עונת 26/27</span></span>
        <span class="tob__price" style="--kit: var(--maroon)"><b>89₪</b><span>רטרו</span></span>
      </div>
      <p class="tob__cond">לחולצה, בהזמנת {{ group_min }} חולצות ומעלה</p>
    </div>
    {%- if mp.featured_image -%}
      <div class="tob__boximg"><img src="{{ mp.featured_image | image_url: width: 840 }}" alt="מיסטרי בוקס - חנות השופט" loading="lazy" decoding="async" width="840" height="840"><small class="tob__ill">התמונה להמחשה בלבד</small></div>
    {%- endif -%}
  </div>

  <div class="tob__wall" aria-label="לקוחות שהזמינו מיסטרי">
    <div class="tob__track" data-track>
      {%- for i in (1..4) -%}
        {%- for u in ugc_list -%}
          <figure class="tob__shot" style="margin-top:0;margin-bottom:0"{% if i > 1 %} aria-hidden="true"{% endif %}>
            <img src="{{ u | strip }}&width=900" alt="{% if i == 1 %}לקוחות של חנות השופט עם חולצות מהמיסטרי{% endif %}" decoding="async">
            <span class="tob__chip">לקוח אמיתי</span>
          </figure>
        {%- endfor -%}
      {%- endfor -%}
    </div>
  </div>

  <div class="tob__builder" id="build-{{ section.id }}">
    <button type="button" class="tob__toggle" data-toggle aria-expanded="false" aria-controls="panel-{{ section.id }}">
      <svg class="box" viewBox="0 0 46 44" aria-hidden="true"><path d="M4 13 23 4l19 9v19l-19 9-19-9z" fill="#c29a6b"/><path d="M4 13l19 9 19-9M23 22v19" stroke="#8a6a44" stroke-width="2" fill="none"/><text x="23" y="34" text-anchor="middle" font-size="15" font-weight="900" fill="#fff">?</text></svg>
      <span class="tob__tt"><b>בונים הזמנה לכל הצוות</b><span data-teaser>בוחרים מידה וגרסה לכל אחד, והמחיר יורד מ־{{ group_min }} חולצות</span></span>
      <span class="tob__open"><span data-toggle-text>להתחלה</span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9l6 6 6-6"/></svg></span>
    </button>
    <div class="tob__panel" id="panel-{{ section.id }}"><div>
      <div class="tob__grid">
        <div class="tob__box">
          <div class="tob__h">
            <span>כמה מיסטרי בוקס?</span>
            <span class="tob__count" aria-label="מספר חולצות">
              <button type="button" data-act="minus" aria-label="פחות">−</button>
              <output data-count>5</output>
              <button type="button" data-act="plus" aria-label="עוד">+</button>
            </span>
          </div>
          <div class="tob__rows" data-rows></div>
          <button type="button" class="tob__add" data-act="plus">+ הוספת חבר</button>
          <div class="tob__team">
            <label>סוג חולצות לכל הצוות<select data-team-shirts></select></label>
            <label>העדפות למיסטרי (לא חובה)<input type="text" data-team-pref placeholder="לדוגמה: בלי ורוד, בלי ארסנל"></label>
          </div>
        </div>
        <div class="tob__box tob__sum">
          <div class="tob__h"><span>המיסטרי בוקס של הצוות</span></div>
          <div class="tob__bar"><i data-bar></i></div>
          <p class="tob__msg" data-msg></p>
          <div class="tob__line"><span data-n></span><s data-reg></s></div>
          <div class="tob__total"><span>סה"כ</span><b data-total></b></div>
          <span class="tob__save" data-save></span>
          <button type="button" class="tob__go" data-go>הוסיפו לעגלה</button>
          <p class="tob__err" data-err role="alert"></p>
          <p class="tob__fine">המחיר הסופי מחושב אוטומטית בעגלה</p>
          <a class="tob__kids" href="{{ url_kids }}">מחפשים לילדים? למיסטרי בוקס ילדים</a>
        </div>
      </div>
    </div></div>
  </div>

  {%- assign team_page = pages['יוצר-מיסטרי'] -%}
  <a class="tob__more" href="{% if team_page and team_page.url %}{{ team_page.url }}{% else %}/pages/יוצר-מיסטרי{% endif %}">כל הפרטים על המיסטרי לצוות</a>

</section>

<script type="application/json" id="tob-data-{{ section.id }}">
{
  "min": {{ group_min }},
  "off": {{ group_off | times: 100 }},
  "options": [{%- for o in mp.options_with_values -%}{"name": {{ o.name | json }}, "values": {{ o.values | json }}}{% unless forloop.last %},{% endunless %}{%- endfor -%}],
  "variants": [{%- for v in mp.variants -%}{"id": {{ v.id }}, "o": [{{ v.option1 | json }}, {{ v.option2 | json }}, {{ v.option3 | json }}], "p": {{ v.price }}, "a": {{ v.available | json }}}{% unless forloop.last %},{% endunless %}{%- endfor -%}]
}
</script>
<script>
(function () {
  var root = document.getElementById('tob-{{ section.id }}');
  var dataEl = document.getElementById('tob-data-{{ section.id }}');
  if (!root || !dataEl || root.dataset.ready) return;
  root.dataset.ready = '1';
  var D = JSON.parse(dataEl.textContent);

  /* ---- full width without a horizontal scrollbar ---- */
  function fitWidth() { root.style.setProperty('--tob-vw', document.documentElement.clientWidth + 'px'); }
  fitWidth(); window.addEventListener('resize', fitWidth);

  /* ---- collapse ---- */
  var builder = root.querySelector('.tob__builder');
  var toggle = root.querySelector('[data-toggle]');
  var toggleText = root.querySelector('[data-toggle-text]');
  function setOpen(open, scroll) {
    builder.classList.toggle('is-open', open);
    builder.classList.remove('is-done');
    toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    toggleText.textContent = open ? 'סגירה' : 'להתחלה';
    if (open) { calc(); setTimeout(function () { builder.classList.add('is-done'); }, 460); }
    if (open && scroll) setTimeout(function () { builder.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 80);
  }
  if (builder.classList.contains('is-open')) builder.classList.add('is-done');
  toggle.addEventListener('click', function () { setOpen(!builder.classList.contains('is-open'), false); });
  root.querySelectorAll('[data-jump]').forEach(function (a) {
    a.addEventListener('click', function (e) { e.preventDefault(); setOpen(true, true); });
  });

  /* ---- builder ---- */
  function idx(word, fallback) {
    for (var i = 0; i < D.options.length; i++) if (D.options[i].name.indexOf(word) > -1) return i;
    return fallback < D.options.length ? fallback : -1;
  }
  var iSize = idx('מידה', 0), iVer = idx('גרסה', 1), iShirt = idx('חולצות', 2);
  var vals = function (i) { return i > -1 ? D.options[i].values : []; };
  var sizes = vals(iSize), versions = vals(iVer), shirts = vals(iShirt);
  var defSize = sizes.indexOf('M') > -1 ? 'M' : sizes[0];

  var rowsEl = root.querySelector('[data-rows]');
  var countEl = root.querySelector('[data-count]');
  var shirtSel = root.querySelector('[data-team-shirts]');
  var prefEl = root.querySelector('[data-team-pref]');
  var goBtn = root.querySelector('[data-go]');
  var errEl = root.querySelector('[data-err]');
  var teaser = root.querySelector('[data-teaser]');
  var rows = [];

  function esc(t) { return String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;'); }
  function label(v) { return v.replace(/^גרסת\s*/, '').replace(/\s*\(\+?₪?\d+₪?\)/, ''); }
  function opts(list, sel) {
    return list.map(function (v) { return '<option value="' + esc(v) + '"' + (v === sel ? ' selected' : '') + '>' + esc(label(v)) + '</option>'; }).join('');
  }
  if (shirts.length) { shirtSel.innerHTML = opts(shirts, shirts[0]); } else { shirtSel.closest('label').style.display = 'none'; }

  function findVariant(size, ver) {
    var want = []; want[iSize] = size; want[iVer] = ver; if (iShirt > -1) want[iShirt] = shirtSel.value;
    return D.variants.find(function (v) {
      for (var i = 0; i < D.options.length; i++) if (want[i] !== undefined && v.o[i] !== want[i]) return false;
      return true;
    });
  }
  function money(c) { var n = c / 100; return (n % 1 ? n.toFixed(2) : n.toLocaleString('he-IL')) + '₪'; }
  var BOX = '<svg viewBox="0 0 36 34" aria-hidden="true"><path d="M3 11 18 4l15 7v15l-15 7-15-7z" fill="#c29a6b"/><path d="M3 11l15 7 15-7M18 18v15" stroke="#8a6a44" stroke-width="1.6" fill="none"/></svg>';

  function draw() {
    rowsEl.innerHTML = rows.map(function (r, i) {
      return '<div class="tob__row" data-i="' + i + '">' +
        '<span class="tob__n">' + BOX + '<b>' + (i + 1) + '</b></span>' +
        '<select aria-label="מידה" data-f="size">' + opts(sizes, r.size) + '</select>' +
        '<select aria-label="גרסה" data-f="ver">' + opts(versions, r.ver) + '</select>' +
        '<button type="button" class="tob__del" aria-label="הסרה" data-del>×</button></div>';
    }).join('');
    calc();
  }
  function calc() {
    var n = rows.length, reg = 0, bad = 0;
    rows.forEach(function (r, i) {
      var v = findVariant(r.size, r.ver); r.v = v;
      var el = rowsEl.children[i];
      if (!v || !v.a) { bad++; el && el.classList.add('is-bad'); } else { el && el.classList.remove('is-bad'); }
      if (v) reg += v.p;
    });
    var group = n >= D.min;
    var total = group ? reg - D.off * n : reg;
    root.classList.toggle('is-group', group);
    countEl.textContent = n;
    root.querySelector('[data-bar]').style.width = Math.min(100, n / D.min * 100) + '%';
    var left = D.min - n;
    root.querySelector('[data-msg]').textContent = group ? 'המחיר הקבוצתי פעיל' :
      (left === 1 ? 'עוד חולצה אחת למחיר הקבוצתי' : 'עוד ' + left + ' חולצות למחיר הקבוצתי');
    root.querySelector('[data-n]').textContent = n + ' מיסטרי בוקס';
    root.querySelector('[data-reg]').textContent = group && n ? money(reg) : '';
    root.querySelector('[data-total]').textContent = money(total);
    root.querySelector('[data-save]').textContent = group ? 'חוסכים ' + money(reg - total) : '';
    if (!goBtn.dataset.busy) goBtn.textContent = 'הוסיפו ' + n + ' מיסטרי בוקס לעגלה';
    if (teaser && builder.classList.contains('is-open')) teaser.textContent = n + ' מיסטרי בוקס, ' + money(total) + (group ? ' (חוסכים ' + money(reg - total) + ')' : '');
    errEl.textContent = bad ? (bad === 1 ? 'אחת המידות שבחרתם אזלה. בחרו מידה או גרסה אחרת' : bad + ' מהבחירות אזלו. בחרו מידה או גרסה אחרת') : '';
    goBtn.disabled = n === 0 || bad > 0;
  }
  function setCount(n) {
    n = Math.max(1, Math.min(40, n));
    while (rows.length < n) { var last = rows[rows.length - 1]; rows.push({ size: last ? last.size : defSize, ver: last ? last.ver : versions[0] }); }
    rows.length = n; draw();
  }

  root.addEventListener('click', function (e) {
    var b = e.target.closest('[data-act],[data-del]'); if (!b) return;
    if (b.dataset.act === 'plus') setCount(rows.length + 1);
    else if (b.dataset.act === 'minus') setCount(rows.length - 1);
    else if (b.hasAttribute('data-del') && rows.length > 1) { rows.splice(+b.closest('.tob__row').dataset.i, 1); draw(); }
  });
  rowsEl.addEventListener('input', function (e) {
    var f = e.target.dataset.f; if (!f) return;
    rows[+e.target.closest('.tob__row').dataset.i][f] = e.target.value; calc();
  });
  shirtSel.addEventListener('change', calc);

  goBtn.addEventListener('click', function () {
    var pref = prefEl.value.trim(), map = {};
    rows.forEach(function (r) {
      var props = {}; if (pref) props['העדפות למיסטרי בוקס'] = pref;
      var key = r.v.id + '|' + JSON.stringify(props);
      if (map[key]) map[key].quantity++; else map[key] = { id: r.v.id, quantity: 1, properties: props };
    });
    goBtn.disabled = true; goBtn.dataset.busy = '1'; goBtn.textContent = 'מוסיפים לעגלה...'; errEl.textContent = '';
    fetch('/cart/add.js', { method: 'POST', headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
      body: JSON.stringify({ items: Object.keys(map).map(function (k) { return map[k]; }) }) })
      .then(function (r) { return r.json().then(function (j) { if (!r.ok) throw j; return j; }); })
      .then(function () { window.location.href = '/cart'; })
      .catch(function (j) {
        errEl.textContent = (j && j.description) ? j.description : 'משהו השתבש. נסו שוב או דברו איתנו בוואטסאפ';
        goBtn.disabled = false; delete goBtn.dataset.busy; calc();
      });
  });

  setCount(D.min);
})();
</script>
{%- endif -%}

