  }
  .tms__card::before {
    content: ""; position: absolute; inset: 0 0 auto 0; height: 62%;
    background:
      radial-gradient(90% 80% at 50% 100%, color-mix(in srgb, var(--c1) 22%, transparent), transparent 70%),
      linear-gradient(180deg, color-mix(in srgb, var(--c1) 10%, #fff), #fff);
    transition: opacity .25s ease;
  }
  .tms__card::after {
    content: ""; position: absolute; inset: 0 0 auto 0; height: 6px;
    background: linear-gradient(90deg, var(--c1) 0 60%, var(--c2) 60% 100%);
  }
  .tms__card:hover { transform: translateY(-4px); box-shadow: 0 16px 34px rgba(0,0,0,.10); border-color: color-mix(in srgb, var(--c1) 35%, var(--line)); }
  .tms__card:focus-visible { outline: 3px solid var(--ink); outline-offset: 3px; }

  .tms__logo {
    position: relative; z-index: 1; width: 108px; height: 108px; margin: 30px 0 14px;
    display: flex; align-items: center; justify-content: center;
  }
