  }
  .tms__count svg { width: 14px; height: 14px; transition: transform .25s ease; }
  .tms__card:hover .tms__count { color: var(--ink); }
  .tms__card:hover .tms__count svg { transform: translateX(-3px); }

  @media (max-width: 900px) {
    .tms { padding: 40px 0 44px; }
    .tms__row {
      display: flex; overflow-x: auto; scroll-snap-type: x mandatory; gap: 10px;
