  .qly__thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
  .qly__thumb[aria-current="true"] { border-color: var(--ink); opacity: 1; }
  .qly__thumb:hover { opacity: 1; }

  .qly__card { background: #fff; border: 1px solid var(--line); border-radius: 22px; padding: 26px; }
