  .qly__specs dt { font-weight: 800; color: var(--muted); }
  .qly__specs dd { margin: 0; font-weight: 700; }
  .qly__note { margin: 16px 0 0; font-size: 13.5px; color: var(--muted); background: var(--sand); border-radius: 12px; padding: 10px 12px; line-height: 1.5; }
  .qly__note a { color: var(--ink); font-weight: 800; text-underline-offset: 3px; }
  .qly__cta { display: flex; justify-content: center; align-items: center; margin-top: 18px; height: 52px; border-radius: 14px; background: var(--ink); color: #fff; text-decoration: none; font-weight: 900; font-size: 16px; }

  /* lightbox */
  .qly__lb { border: 0; padding: 0; background: transparent; max-width: 100vw; max-height: 100vh; width: 100vw; height: 100vh; }
  .qly__lb::backdrop { background: rgba(10,10,10,.88); }
  .qly__lb[open] { display: flex; align-items: center; justify-content: center; }
  .qly__lb img { max-width: min(92vw, 1100px); max-height: 86vh; border-radius: 16px; display: block; }
  .qly__lbbtn {
    position: fixed; width: 48px; height: 48px; border-radius: 50%; border: 0; background: #fff; color: var(--ink);
    display: flex; align-items: center; justify-content: center; cursor: pointer; font-size: 22px; font-weight: 900;
  }
  .qly__lbbtn svg { width: 22px; height: 22px; }
  .qly__lbx { top: 18px; left: 18px; }
  .qly__lbp { top: 50%; right: 18px; transform: translateY(-50%); }
  .qly__lbn { top: 50%; left: 18px; transform: translateY(-50%); }

  @media (max-width: 860px) {
    .qly { padding: 42px 0 46px; }
    .qly__panel { grid-template-columns: 1fr; }
    .qly__tab { padding: 10px 18px; font-size: 15px; }
    .qly__name { font-size: 24px; }
    .qly__specs div { grid-template-columns: 84px 1fr; }
    .qly__lbp, .qly__lbn { top: auto; bottom: 22px; transform: none; }
    .qly__lbp { right: calc(50% - 60px); } .qly__lbn { left: calc(50% - 60px); }
  }
  @media (prefers-reduced-motion: reduce) { .qly__main img, .qly__tab, .qly__thumb { transition: none; } }
</style>

